<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Name Generator Online','description'=>'Generate random names for projects, characters, brands and more.','url'=>'https://smarttoolz.in/tools/name-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">NAME GENERATOR</span><h1>Random Name Generator</h1><p>Generate simple random first-name and last-name combinations.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Number of names<input id="n" type="number" min="1" max="50" value="10"></label><button id="go" class="tool-btn">Generate Names</button><textarea id="out" rows="12" readonly style="margin-top:15px;width:100%;box-sizing:border-box"></textarea><button id="copy" class="tool-btn" style="margin-top:10px">Copy All</button></div></section></main><script>(()=>{const f=['Aarav','Aanya','Arjun','Maya','Riya','Kabir','Neha','Ishaan','Sara','Vihaan','Anaya','Dev','Meera','Ryan','Zoya','Kian'],l=['Sharma','Patel','Singh','Verma','Kapoor','Mehta','Khan','Gupta','Nair','Joshi'];const o=document.getElementById('out'),n=document.getElementById('n');document.getElementById('go').onclick=()=>o.value=Array.from({length:Math.min(50,Math.max(1,+n.value||1))},()=>f[Math.random()*f.length|0]+' '+l[Math.random()*l.length|0]).join('\n');document.getElementById('copy').onclick=()=>navigator.clipboard.writeText(o.value);document.getElementById('go').click()})();</script><?php smarttoolz_tool_page_end(); ?>